package com.clothingstore;
import org.springframework.beans.factory.annotation.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import org.springframework.security.crypto.password.PasswordEncoder;
@Configuration public class AdminBootstrap { @Bean CommandLineRunner initialAdmin(UserAccountRepository users,PasswordEncoder encoder,@Value("${app.initial-admin-email:}") String email,@Value("${app.initial-admin-password:}") String password){return args->{if(!email.isBlank()&&!password.isBlank()&&!users.existsByEmail(email.toLowerCase())){UserAccount admin=new UserAccount();admin.setFullName("LUXE Administrator");admin.setEmail(email);admin.setPasswordHash(encoder.encode(password));admin.setRole("ADMIN");users.save(admin);}};} }
